   250→            StateRoot = baseBlock?.StateRoot ?? Keccak.EmptyTreeHash;
   251→            IDisposable trieStoreCloser = _trieStore.BeginScope(baseBlock);
   252→
   253→            return new Reactive.AnonymousDisposable(() =>
   254→            {
   255→                Reset();
   256→                StateRoot = Keccak.EmptyTreeHash;
   257→                trieStoreCloser.Dispose();
   258→                _isInScope = false;
   259→                if (_logger.IsTrace) _logger.Trace($"WorldState scope for baseblock {baseBlock?.ToString(BlockHeader.Format.Short) ?? "null"} closed");
   260→            });
   261→        }
